; BOOTUP.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; CREATE: register, terminate, create a character, then load EXODUS.BIN (194B-1E34).
;
; Overview: the roster commands of the party menu: ExamineRegister (ExamineRegister, list the 20
; slots), TerminateChar and CreateChar (CreateChar, with DrawCreateForm, EnterCharacter
; and ShowPointsLeft: name, sex, race, type and 50 points for the four attributes). Then the
; helpers used by the whole program: WaitSpace, PartyToRoster / RosterToParty (copy records
; between the party and the roster), RosterRecord, AnimateDemo (AnimateDemo, for the
; title), CheckAlive and AnyAlive, AskNumber, and AskScenarioDisk,
; disabled by a patched ret. (The chain load of EXODUS.BIN is JourneyOnward, TITLE.ASM.)
; A roster number is asked as "Entry#" and must be 1-20 ("(1-20 Only!)").
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN CursorCol:BYTE
EXTRN TileGfx:BYTE
EXTRN SwapCursor:NEAR
EXTRN PutChar:NEAR
EXTRN DrawTileBlock:NEAR
EXTRN ReadLine:NEAR
EXTRN AnimScroll:NEAR
EXTRN AnimFlags:NEAR
EXTRN SwapFrames:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN PrintBcdByte:NEAR
EXTRN AskChoice:NEAR
EXTRN ReadNumber:NEAR
EXTRN SaveFile:NEAR
EXTRN PrintAt:NEAR
EXTRN Sound:NEAR
EXTRN PartySize:BYTE
EXTRN PartyRosterNums:BYTE
EXTRN PartyChars:BYTE
EXTRN Roster:BYTE
EXTRN DemoTiles:BYTE
EXTRN FileRosterUlt:BYTE
EXTRN MsgPressSpace:BYTE
EXTRN MsgEntry:BYTE
EXTRN MsgOnly1To20:BYTE
EXTRN MsgRegister:BYTE
EXTRN MsgTerminateTitle:BYTE
EXTRN MsgNoOneThere:BYTE
EXTRN MsgWithParty:BYTE
EXTRN MsgTerminated:BYTE
EXTRN MsgCreateTitle:BYTE
EXTRN MsgNotEmpty:BYTE
EXTRN MsgPoints50:BYTE
EXTRN MsgNameColon:BYTE
EXTRN MsgSexColon:BYTE
EXTRN MsgRaceColon:BYTE
EXTRN MsgTypeColon:BYTE
EXTRN MsgStrengthDots:BYTE
EXTRN MsgDexterityDots:BYTE
EXTRN MsgIntelligenceDots:BYTE
EXTRN MsgWisdomDots:BYTE
EXTRN MsgOK:BYTE
EXTRN SexKeys:BYTE
EXTRN SexNames:BYTE
EXTRN RaceKeys:BYTE
EXTRN RaceNames:BYTE
EXTRN ClassKeys:BYTE
EXTRN ClassNames:BYTE
EXTRN YesNoKeys:BYTE
EXTRN YesNoNames:BYTE
EXTRN ClearMenu:NEAR
PUBLIC ExamineRegister
PUBLIC TerminateChar
PUBLIC CreateChar
PUBLIC WaitSpace
PUBLIC PartyToRoster
PUBLIC RosterToParty
PUBLIC RosterRecord
PUBLIC AnimateDemo
PUBLIC AnyAlive
PUBLIC AskScenarioDisk
PUBLIC AskNumber
;------------------------------------------------------------------------------
; ExamineRegister: "Examine the Register": list the 20 roster slots in two columns
; (1-10 at column 1, 11-20 at column 20, rows 13-22). A used slot shows its number, '-' (or
; '*' when in the party), the sex, race, class and status letters and the name.
; Uses: AX, BX, CX.
;------------------------------------------------------------------------------
ExamineRegister:	pushf	;@194B
	push dx	;@194C
	push si	;@194D
	call ClearMenu	;@194E
	mov dh, 0Bh	;@1951
	mov dl, 10h	;@1953
	lea si, MsgRegister	; "Register"	;@1955
	call PrintAt	;@1959
	mov al, 1	; AL = the number in BCD ...	;@195C
	mov ah, 1	; ... AH in binary	;@195E
ExamineReg_Entry:	mov dl, 1	;@1960
	mov dh, ah	;@1962
	add dh, 0Ch	;@1964
	cmp dh, 17h	;@1967
	jb ExamineReg_Print	;@196A
	sub dh, 0Ah	; 11-20: second column	;@196C
	mov dl, 14h	;@196F
ExamineReg_Print:	call SwapCursor	;@1971
	mov bl, al	; (no effect: BL is set again below)	;@1974
	call PrintBcdByte	;@1976
	mov bl, ah	;@1979
	call RosterRecord	; RosterRecord	;@197B
	cmp byte ptr [bx], 0	;@197E
	je ExamineReg_Next	;@1981
	push ax	;@1983
	cmp byte ptr [bx+10h], 0FFh	; in the party?	;@1984
	je ExamineReg_InParty	;@1988
	mov al, 2Dh	; '-'	;@198A
	call PutChar	;@198C
	jmp short ExamineReg_Letters	;@198F
ExamineReg_InParty:	mov al, 2Ah	; '*'	;@1991
	call PutChar	;@1993
ExamineReg_Letters:	mov al, 20h	;@1996
	call PutChar	;@1998
	mov al, byte ptr [bx+18h]	; sex	;@199B
	call PutChar	;@199E
	mov al, byte ptr [bx+16h]	; race	;@19A1
	call PutChar	;@19A4
	mov al, byte ptr [bx+17h]	; class	;@19A7
	call PutChar	;@19AA
	mov al, byte ptr [bx+11h]	; status	;@19AD
	call PutChar	;@19B0
	mov al, 20h	;@19B3
	call PutChar	;@19B5
	lea si, [bx]	; the name, at most 14 characters	;@19B8
	mov cx, 0Eh	;@19BA
ExamineReg_Name:	lodsb	;@19BD
	cmp al, 0	;@19BE
	je ExamineReg_EndName	;@19C0
	call PutChar	;@19C2
	loop ExamineReg_Name	;@19C5
ExamineReg_EndName:	pop ax	;@19C7
ExamineReg_Next:	add al, 1	;@19C8
	daa	;@19CA
	inc ah	;@19CB
	cmp ah, 14h	;@19CD
	ja ExamineReg_Done	;@19D0
	jmp ExamineReg_Entry	;@19D2
ExamineReg_Done:	call WaitSpace	;@19D4
	pop si	;@19D7
	pop dx	;@19D8
	popf	;@19D9
	ret	;@19DA
;------------------------------------------------------------------------------
; TerminateChar: "Terminate!": ask a roster number and erase that character (zero
; the record, save ROSTER.ULT): "(Terminated)". Refused: "(1-20 Only!)", "(No one there)",
; "(With a party)" for a member of the party. Uses: nothing.
;------------------------------------------------------------------------------
TerminateChar:	pushf	;@19DB
	push ax	;@19DC
	push bx	;@19DD
	push cx	;@19DE
	push dx	;@19DF
	push si	;@19E0
	push di	;@19E1
	cld	;@19E2
	call ClearMenu	;@19E3
	mov dh, 0Fh	;@19E6
	mov dl, 0Fh	;@19E8
	lea si, MsgTerminateTitle	;@19EA
	call PrintAt	;@19EE
	mov dh, 12h	;@19F1
	mov dl, 10h	;@19F3
	lea si, MsgEntry	;@19F5
	call PrintAt	;@19F9
	call AskNumber	; AskNumber: AL = BCD, AH = binary	;@19FC
	cmp ah, 0	;@19FF
	je TerminateChar_BadNum	;@1A02
	cmp ah, 14h	;@1A04
	ja TerminateChar_BadNum	;@1A07
	mov bl, ah	;@1A09
	call RosterRecord	; RosterRecord	;@1A0B
	cmp byte ptr [bx], 0	;@1A0E
	je TerminateChar_NoOne	;@1A11
	cmp byte ptr [bx+10h], 0FFh	; in the party?	;@1A13
	je TerminateChar_InParty	;@1A17
	mov cx, 40h	;@1A19
	mov di, bx	;@1A1C
	mov al, 0	;@1A1E
	rep stosb	;@1A20
	mov dh, 15h	;@1A22
	mov dl, 0Eh	;@1A24
	lea si, MsgTerminated	;@1A26
	call PrintAt	;@1A2A
	lea dx, FileRosterUlt	;@1A2D
	mov cx, 500h	;@1A31
	lea bx, Roster	;@1A34
	call SaveFile	;@1A38
TerminateChar_Done:	call WaitSpace	;@1A3B
	pop di	;@1A3E
	pop si	;@1A3F
	pop dx	;@1A40
	pop cx	;@1A41
	pop bx	;@1A42
	pop ax	;@1A43
	popf	;@1A44
	ret	;@1A45
TerminateChar_BadNum:	mov dh, 15h	;@1A46
	mov dl, 0Eh	;@1A48
	lea si, MsgOnly1To20	;@1A4A
	call PrintAt	;@1A4E
	jmp TerminateChar_Done	;@1A51
TerminateChar_NoOne:	mov dh, 14h	;@1A53
	mov dl, 0Dh	;@1A55
	lea si, MsgNoOneThere	;@1A57
	call PrintAt	;@1A5B
	jmp TerminateChar_Done	;@1A5E
TerminateChar_InParty:	mov dh, 15h	;@1A60
	mov dl, 0Dh	;@1A62
	lea si, MsgWithParty	;@1A64
	call PrintAt	;@1A68
	jmp TerminateChar_Done	;@1A6B
;------------------------------------------------------------------------------
; CreateChar: "Create": ask a roster number; the slot must be empty ("(Not
; Empty!)"). Show the form (DrawCreateForm), enter the character (EnterCharacter; an empty
; name gives up), then "O.K.?" Yes/No. Yes: status G, not in a party, 150 hit points and
; maximum, 150 food, 150 gold, one weapon of kind 1 (Dagger, +31h) and one armour of kind
; 1 (Cloth, +29h), though Hand and Skin stay readied and worn; save ROSTER.ULT. No: the
; slot is cleared again. Uses: nothing.
;------------------------------------------------------------------------------
CreateChar:	pushf	;@1A6D
	push ax	;@1A6E
	push bx	;@1A6F
	push cx	;@1A70
	push dx	;@1A71
	push si	;@1A72
	push di	;@1A73
	call ClearMenu	;@1A74
	mov dh, 0Fh	;@1A77
	mov dl, 11h	;@1A79
	lea si, MsgCreateTitle	;@1A7B
	call PrintAt	;@1A7F
	mov dh, 12h	;@1A82
	mov dl, 10h	;@1A84
	lea si, MsgEntry	;@1A86
	call PrintAt	;@1A8A
	call AskNumber	; AskNumber: AL = BCD, AH = binary	;@1A8D
	cmp ah, 0	;@1A90
	je CreateChar_BadNum	;@1A93
	cmp ah, 14h	;@1A95
	ja CreateChar_BadNum	;@1A98
	mov dl, al	;@1A9A
	mov bl, ah	;@1A9C
	call RosterRecord	; RosterRecord	;@1A9E
	cmp byte ptr [bx], 0	;@1AA1
	jne CreateChar_NotEmpty	;@1AA4
	mov di, bx	;@1AA6
	mov cx, 40h	;@1AA8
	mov al, 0	;@1AAB
	rep stosb	;@1AAD
	call DrawCreateForm	;@1AAF
	mov al, dl	;@1AB2
	mov dh, 0Bh	;@1AB4
	mov dl, 11h	;@1AB6
	call SwapCursor	;@1AB8
	call PrintBcdByte	;@1ABB
	call EnterCharacter	;@1ABE
	cmp byte ptr [bx], 0	; no name?	;@1AC1
	je CreateChar_Discard	;@1AC4
CreateChar_AskOK:	mov dh, 15h	;@1AC6
	mov dl, 13h	; after "O.K.?"	;@1AC8
	call SwapCursor	;@1ACA
	mov cx, 2	;@1ACD
	lea di, YesNoKeys	; "YN"	;@1AD0
	lea si, YesNoNames	;@1AD4
	call AskChoice	;@1AD8
	cmp al, 59h	; 'Y'	;@1ADB
	je CreateChar_Accept	;@1ADD
	cmp al, 4Eh	; 'N'	;@1ADF
	je CreateChar_Discard	;@1AE1
	jmp CreateChar_AskOK	;@1AE3
CreateChar_BadNum:	mov dh, 15h	;@1AE5
	mov dl, 0Eh	;@1AE7
	lea si, MsgOnly1To20	;@1AE9
	call PrintAt	;@1AED
	jmp short CreateChar_Done	;@1AF0
CreateChar_NotEmpty:	mov dh, 15h	;@1AF2
	mov dl, 0Eh	;@1AF4
	lea si, MsgNotEmpty	;@1AF6
	call PrintAt	;@1AFA
	jmp short CreateChar_Done	;@1AFD
CreateChar_Accept:	mov byte ptr [bx+11h], 47h	; status 'G' good	;@1AFF
	mov byte ptr [bx+10h], 0	; not in a party	;@1B03
	mov word ptr [bx+1Ah], 150h	; hit points 150 (BCD)	;@1B07
	mov word ptr [bx+1Ch], 150h	; maximum hit points	;@1B0C
	mov word ptr [bx+21h], 150h	; food	;@1B11
	mov word ptr [bx+23h], 150h	; gold	;@1B16
	mov byte ptr [bx+31h], 1	; one Dagger (weapon kind 1)	;@1B1B
	mov byte ptr [bx+29h], 1	; one Cloth (armour kind 1)	;@1B1F
	lea dx, FileRosterUlt	;@1B23
	mov cx, 500h	;@1B27
	lea bx, Roster	;@1B2A
	call SaveFile	;@1B2E
	jmp short CreateChar_Done	;@1B31
CreateChar_Discard:	mov al, 0	;@1B33
	mov cx, 40h	;@1B35
	mov di, bx	;@1B38
	rep stosb	;@1B3A
CreateChar_Done:	call WaitSpace	;@1B3C
	pop di	;@1B3F
	pop si	;@1B40
	pop dx	;@1B41
	pop cx	;@1B42
	pop bx	;@1B43
	pop ax	;@1B44
	popf	;@1B45
	ret	;@1B46
;------------------------------------------------------------------------------
; DrawCreateForm: clear the menu area and print the creation form: "Entry#" and
; "Points:50" (row 11), Name, Sex, Race, Type (rows 13-16, column 14), the four attributes
; (rows 17-20) and "O.K.?" (row 21). Uses: nothing.
;------------------------------------------------------------------------------
DrawCreateForm:	push dx	;@1B47
	push si	;@1B48
	call ClearMenu	;@1B49
	mov dh, 0Bh	;@1B4C
	mov dl, 0Bh	;@1B4E
	lea si, MsgEntry	;@1B50
	call PrintAt	;@1B54
	mov dh, 0Bh	;@1B57
	mov dl, 14h	;@1B59
	lea si, MsgPoints50	;@1B5B
	call PrintAt	;@1B5F
	mov dh, 0Dh	;@1B62
	mov dl, 0Eh	;@1B64
	lea si, MsgNameColon	;@1B66
	call PrintAt	;@1B6A
	mov dh, 0Eh	;@1B6D
	mov dl, 0Eh	;@1B6F
	lea si, MsgSexColon	;@1B71
	call PrintAt	;@1B75
	mov dh, 0Fh	;@1B78
	mov dl, 0Eh	;@1B7A
	lea si, MsgRaceColon	;@1B7C
	call PrintAt	;@1B80
	mov dh, 10h	;@1B83
	mov dl, 0Eh	;@1B85
	lea si, MsgTypeColon	;@1B87
	call PrintAt	;@1B8B
	mov dh, 11h	;@1B8E
	mov dl, 0Bh	;@1B90
	lea si, MsgStrengthDots	;@1B92
	call PrintAt	;@1B96
	mov dh, 12h	;@1B99
	mov dl, 0Bh	;@1B9B
	lea si, MsgDexterityDots	;@1B9D
	call PrintAt	;@1BA1
	mov dh, 13h	;@1BA4
	mov dl, 0Bh	;@1BA6
	lea si, MsgIntelligenceDots	;@1BA8
	call PrintAt	;@1BAC
	mov dh, 14h	;@1BAF
	mov dl, 0Bh	;@1BB1
	lea si, MsgWisdomDots	;@1BB3
	call PrintAt	;@1BB7
	mov dh, 15h	;@1BBA
	mov dl, 0Eh	;@1BBC
	lea si, MsgOK	;@1BBE
	call PrintAt	;@1BC2
	pop si	;@1BC5
	pop dx	;@1BC6
	ret	;@1BC7
;------------------------------------------------------------------------------
; EnterCharacter: fill the empty record at BX from the creation form: the name (at most 9
; letters; an empty name returns at once), sex, race and type chosen with AskChoice (key, name,
; Enter), then the attributes, each 5-25, from 50 points (BCD in CL): strength; dexterity
; leaving at least 10; intelligence leaving at least 5; wisdom at most what is left. Points
; not spent are lost. In: BX = the record. Uses: nothing.
;------------------------------------------------------------------------------
EnterCharacter:	pushf	;@1BC8
	push ax	;@1BC9
	push bx	;@1BCA
	push cx	;@1BCB
	push dx	;@1BCC
	push si	;@1BCD
	push di	;@1BCE
	mov dh, 0Dh	;@1BCF
	mov dl, 13h	; after "Name:"	;@1BD1
	call SwapCursor	;@1BD3
	push bx	;@1BD6
	mov cx, 9	;@1BD7
	lea di, [bx]	; +00 the name	;@1BDA
	call ReadLine	; BX out = the length	;@1BDC
	mov byte ptr [bx+di], 0	;@1BDF
	test bx, 0FFFFh	;@1BE2
	pop bx	;@1BE6
	jne EnterChar_Sex	;@1BE7
	jmp EnterChar_Done	;@1BE9
EnterChar_Sex:	mov dh, 0Eh	;@1BEC
	mov dl, 13h	;@1BEE
	call SwapCursor	;@1BF0
	mov cx, 3	;@1BF3
	lea di, SexKeys	;@1BF6
	lea si, SexNames	;@1BFA
	call AskChoice	;@1BFE
	mov byte ptr [bx+18h], al	; sex letter	;@1C01
	mov dh, 0Fh	;@1C04
	mov dl, 13h	;@1C06
	call SwapCursor	;@1C08
	mov cx, 5	;@1C0B
	lea di, RaceKeys	;@1C0E
	lea si, RaceNames	;@1C12
	call AskChoice	;@1C16
	mov byte ptr [bx+16h], al	; race letter	;@1C19
	mov dh, 10h	;@1C1C
	mov dl, 13h	;@1C1E
	call SwapCursor	;@1C20
	mov cx, 0Bh	;@1C23
	lea di, ClassKeys	;@1C26
	lea si, ClassNames	;@1C2A
	call AskChoice	;@1C2E
	mov byte ptr [bx+17h], al	; class letter	;@1C31
	mov cl, 50h	; 50 points (BCD)	;@1C34
EnterChar_Str:	mov dh, 11h	;@1C36
	mov dl, 1Bh	;@1C38
	call SwapCursor	;@1C3A
	call AskNumber	; AskNumber: AL = BCD, AH = binary	;@1C3D
	cmp ah, 19h	; 25	;@1C40
	ja EnterChar_Str	;@1C43
	cmp ah, 5	;@1C45
	jb EnterChar_Str	;@1C48
	mov byte ptr [bx+12h], al	; strength	;@1C4A
	sub cl, al	;@1C4D
	mov al, cl	;@1C4F
	das	; (on the flags of the sub)	;@1C51
	mov cl, al	;@1C52
	call ShowPointsLeft	;@1C54
EnterChar_Dex:	mov dh, 12h	;@1C57
	mov dl, 1Bh	;@1C59
	call SwapCursor	;@1C5B
	call AskNumber	;@1C5E
	cmp ah, 19h	;@1C61
	ja EnterChar_Dex	;@1C64
	cmp ah, 5	;@1C66
	jb EnterChar_Dex	;@1C69
	mov byte ptr [bx+13h], al	; dexterity	;@1C6B
	mov ch, cl	;@1C6E
	sub ch, al	;@1C70
	mov al, ch	;@1C72
	das	;@1C74
	cmp al, 10h	; at least 10 left for the other two	;@1C75
	jb EnterChar_Dex	;@1C77
	mov cl, al	;@1C79
	call ShowPointsLeft	;@1C7B
EnterChar_Int:	mov dh, 13h	;@1C7E
	mov dl, 1Bh	;@1C80
	call SwapCursor	;@1C82
	call AskNumber	;@1C85
	cmp ah, 19h	;@1C88
	ja EnterChar_Int	;@1C8B
	cmp ah, 5	;@1C8D
	jb EnterChar_Int	;@1C90
	mov byte ptr [bx+14h], al	; intelligence	;@1C92
	mov ch, cl	;@1C95
	sub ch, al	;@1C97
	js EnterChar_Int	; more than is left	;@1C99
	mov al, ch	;@1C9B
	das	;@1C9D
	cmp al, 5	; at least 5 left for wisdom	;@1C9E
	jb EnterChar_Int	;@1CA0
	mov cl, al	;@1CA2
	call ShowPointsLeft	;@1CA4
EnterChar_Wis:	mov dh, 14h	;@1CA7
	mov dl, 1Bh	;@1CA9
	call SwapCursor	;@1CAB
	call AskNumber	;@1CAE
	cmp ah, 19h	;@1CB1
	ja EnterChar_Wis	;@1CB4
	cmp ah, 5	;@1CB6
	jb EnterChar_Wis	;@1CB9
	cmp cl, al	; no more than is left	;@1CBB
	jb EnterChar_Wis	;@1CBD
	mov byte ptr [bx+15h], al	; wisdom	;@1CBF
	sub cl, al	;@1CC2
	mov al, cl	;@1CC4
	das	;@1CC6
	mov cl, al	;@1CC7
	call ShowPointsLeft	;@1CC9
EnterChar_Done:	pop di	;@1CCC
	pop si	;@1CCD
	pop dx	;@1CCE
	pop cx	;@1CCF
	pop bx	;@1CD0
	pop ax	;@1CD1
	popf	;@1CD2
	ret	;@1CD3
;------------------------------------------------------------------------------
; ShowPointsLeft: print the points left (CL, BCD) over the 50 of "Points:50" (row 11,
; column 27). In: CL. Uses: nothing.
;------------------------------------------------------------------------------
ShowPointsLeft:	pushf	;@1CD4
	push ax	;@1CD5
	push dx	;@1CD6
	mov dh, 0Bh	;@1CD7
	mov dl, 1Bh	;@1CD9
	call SwapCursor	;@1CDB
	mov al, cl	;@1CDE
	call PrintBcdByte	;@1CE0
	pop dx	;@1CE3
	pop ax	;@1CE4
	popf	;@1CE5
	ret	;@1CE6
;------------------------------------------------------------------------------
; WaitSpace: print "Press <Space>" on the bottom line of the frame (row 23) and wait
; until the space bar is pressed (other keys are ignored). Uses: nothing.
;------------------------------------------------------------------------------
WaitSpace:	pushf	;@1CE7
	push ax	;@1CE8
	push dx	;@1CE9
	push si	;@1CEA
	mov dh, 17h	;@1CEB
	mov dl, 0Ch	;@1CED
	lea si, MsgPressSpace	;@1CEF
	call PrintAt	;@1CF3
WaitSpace_Loop:	call KeyReady	;@1CF6
	je WaitSpace_Loop	;@1CF9
	call ReadKey	;@1CFB
	cmp al, 20h	;@1CFE
	jne WaitSpace_Loop	;@1D00
	pop si	;@1D02
	pop dx	;@1D03
	pop ax	;@1D04
	popf	;@1D05
	ret	;@1D06
;------------------------------------------------------------------------------
; PartyToRoster: copy each of the party's records (PartyChars, PartySize of them) back
; to the roster slot whose number is in PartyRosterNums. Uses: CX.
;------------------------------------------------------------------------------
PartyToRoster:	pushf	;@1D07
	push bx	;@1D08
	push dx	;@1D09
	push si	;@1D0A
	push di	;@1D0B
	cld	;@1D0C
	lea si, PartyChars	;@1D0D
	mov dx, 0	;@1D11
PartyToRoster_Loop:	lea di, PartyRosterNums	;@1D14
	mov bx, dx	;@1D18
	mov bl, byte ptr [bx+di]	;@1D1A
	call RosterRecord	;@1D1C
	mov di, bx	;@1D1F
	mov cx, 40h	;@1D21
	rep movsb	;@1D24
	inc dl	;@1D26
	cmp dl, byte ptr PartySize	;@1D28
	jb PartyToRoster_Loop	;@1D2C
	pop di	;@1D2E
	pop si	;@1D2F
	pop dx	;@1D30
	pop bx	;@1D31
	popf	;@1D32
	ret	;@1D33
;------------------------------------------------------------------------------
; RosterToParty: copy the roster records of the members (numbers in PartyRosterNums) into
; the party's records (PartyChars). Uses: CX.
;------------------------------------------------------------------------------
RosterToParty:	pushf	;@1D34
	push bx	;@1D35
	push dx	;@1D36
	push si	;@1D37
	push di	;@1D38
	cld	;@1D39
	lea di, PartyChars	;@1D3A
	mov dx, 0	;@1D3E
RosterToParty_Loop:	lea si, PartyRosterNums	;@1D41
	mov bx, dx	;@1D45
	mov bl, byte ptr [bx+si]	;@1D47
	call RosterRecord	;@1D49
	mov si, bx	;@1D4C
	mov cx, 40h	;@1D4E
	rep movsb	;@1D51
	inc dl	;@1D53
	cmp dl, byte ptr PartySize	;@1D55
	jb RosterToParty_Loop	;@1D59
	pop di	;@1D5B
	pop si	;@1D5C
	pop dx	;@1D5D
	pop bx	;@1D5E
	popf	;@1D5F
	ret	;@1D60
;------------------------------------------------------------------------------
; RosterRecord: BX = Roster + (BL - 1) * 40h, the record of roster number BL
; (1-20). In: BL. Out: BX. Uses: nothing else.
;------------------------------------------------------------------------------
RosterRecord:	pushf	;@1D61
	push ax	;@1D62
	mov al, 40h	;@1D63
	dec bl	;@1D65
	mul bl	;@1D67
	mov bx, offset Roster	;@1D69
	add bx, ax	;@1D6C
	pop ax	;@1D6E
	popf	;@1D6F
	ret	;@1D70
;------------------------------------------------------------------------------
; AnimateDemo: one frame of the title landscape: the library's tile animations
; (AnimScroll, AnimFlags, SwapFrames: they change tile graphics in TileGfx on their own counters) and the
; DEMO.ULT block redrawn (6 x 19 tiles at text row 11, column 1). Saves AX, BX, BP, DI.
;------------------------------------------------------------------------------
AnimateDemo:	push ax	;@1D71
	push bx	;@1D72
	push bp	;@1D73
	push di	;@1D74
	call AnimScroll	;@1D75
	call AnimFlags	;@1D78
	call SwapFrames	;@1D7B
	mov ah, 6	;@1D7E
	mov al, 13h	;@1D80
	lea bx, DemoTiles	;@1D82
	lea bp, TileGfx	;@1D86
	mov di, 0DC2h	;@1D8A
	call DrawTileBlock	;@1D8D
	pop di	;@1D90
	pop bp	;@1D91
	pop bx	;@1D92
	pop ax	;@1D93
	ret	;@1D94
;------------------------------------------------------------------------------
; CheckAlive: AL = 0 when the record at BX is Good or Poisoned, else 0FFh (dead, ashes or
; empty). In: BX. Out: AL.
;------------------------------------------------------------------------------
CheckAlive:	pushf	;@1D95
	mov al, 0	;@1D96
	cmp byte ptr [bx+11h], 47h	; status 'G'	;@1D98
	je CheckAlive_Done	;@1D9C
	cmp byte ptr [bx+11h], 50h	; status 'P'	;@1D9E
	je CheckAlive_Done	;@1DA2
	mov al, 0FFh	;@1DA4
CheckAlive_Done:	popf	;@1DA6
	ret	;@1DA7
;------------------------------------------------------------------------------
; AnyAlive: AH = 0FFh when one of the four party records (PartyChars, all four whatever
; the party size) is Good or Poisoned, else 0. Out: AH. Uses: AL.
;------------------------------------------------------------------------------
AnyAlive:	pushf	;@1DA8
	push bx	;@1DA9
	push cx	;@1DAA
	lea bx, PartyChars	;@1DAB
	mov cx, 4	;@1DAF
	mov ah, 0FFh	;@1DB2
AnyAlive_Loop:	call CheckAlive	;@1DB4
	cmp al, 0	;@1DB7
	je AnyAlive_Done	;@1DB9
	add bx, 40h	;@1DBB
	loop AnyAlive_Loop	;@1DBE
	mov ah, 0	;@1DC0
AnyAlive_Done:	pop cx	;@1DC2
	pop bx	;@1DC3
	popf	;@1DC4
	ret	;@1DC5
;------------------------------------------------------------------------------
; AskScenarioDisk: disabled. Its first instruction, "mov dh, 17h" (B6 17), had its
; B6 replaced by a ret (C3), so StartUp's call returns at once and the 17h and the rest,
; 1DC7-1E0B, are dead. Decoded, the routine was:
;   mov dh,17h / mov dl,8 / lea si,[0C90h] / call PrintAt  ; "<Insert Scenario Disk>"
;   call DiskCheckStub / mov [DiskCheckResult],al                     ; DiskCheckResult
;   wait for a key (KeyReady, ReadKey); '1'-'4', 'a'-'d' or 'A'-'D' select drive 0-3 as
;   the default drive (DOS 0Eh); any other key keeps the current one; ret.
; So DiskCheckResult stays 0 and JourneyOnward's "(Strange Disk)" cannot happen.
;------------------------------------------------------------------------------
AskScenarioDisk:	ret	;@1DC6
	db 17h,0B2h,8h,8Dh,36h,90h,0Ch,0E8h,0EDh,2Ch,0E8h,0DCh,26h,0A2h,0B9h,1h	;@1DC7
	db 0E8h,10h,2Ah,74h,0FBh,0E8h,1Eh,2Ah,3Ch,31h,72h,0Eh,3Ch,34h,77h,0Ah	;@1DD7
	db 2Ch,31h,8Ah,0D0h,0B4h,0Eh,0CDh,21h,0EBh,1Ah,3Ch,61h,72h,6h,3Ch,64h	;@1DE7
	db 77h,2h,4h,0E0h,3Ch,41h,72h,0Ch,3Ch,44h,77h,8h,2Ch,41h,8Ah,0D0h	;@1DF7
	db 0B4h,0Eh,0CDh,21h,0C3h	;@1E07
;------------------------------------------------------------------------------
; AskNumber: read a number of up to two digits at the cursor (ReadNumber); on a bad
; entry beep (sound 0FEh), blank the two places and ask again. Out: AL = the number in BCD,
; AH = in binary. Uses: nothing else.
;------------------------------------------------------------------------------
AskNumber:	pushf	;@1E0C
	push dx	;@1E0D
	mov dx, word ptr CursorCol	;@1E0E
AskNumber_Retry:	call ReadNumber	;@1E12
	cmp ah, 0FFh	;@1E15
	jne AskNumber_Done	;@1E18
	mov al, 0FEh	;@1E1A
	call Sound	;@1E1C
	mov word ptr CursorCol, dx	;@1E1F
	mov al, 20h	;@1E23
	call PutChar	;@1E25
	call PutChar	;@1E28
	mov word ptr CursorCol, dx	;@1E2B
	jmp AskNumber_Retry	;@1E2F
AskNumber_Done:	pop dx	;@1E31
	popf	;@1E32
	ret	;@1E33
CODE ENDS
END
